--
-- Triggers `inventories`
--
DELIMITER $$
CREATE TRIGGER `inventoryItemsInStockCreateTrigger` AFTER INSERT ON `inventories` FOR EACH ROW BEGIN
    SET @instock=(SELECT SUM(inventories.qty) as instock FROM `inventories` where inventories.status = '1' and inventories.inventory_item_id = new.inventory_item_id group by inventories.inventory_item_id);
    IF @instock is null OR @instock='' THEN
        UPDATE inventory_items set inventory_items.item_instock = '0' where inventory_items.id = new.inventory_item_id;
	ELSE 
		UPDATE inventory_items set inventory_items.item_instock = @instock where inventory_items.id = new.inventory_item_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `inventoryItemsInStockUpdateTrigger` AFTER UPDATE ON `inventories` FOR EACH ROW BEGIN
	SET @instock=(SELECT SUM(inventories.qty) as instock FROM `inventories` where inventories.status = '1' and inventories.inventory_item_id = new.inventory_item_id group by inventories.inventory_item_id);
    IF @instock is null OR @instock='' THEN
        UPDATE inventory_items set inventory_items.item_instock = '0' where inventory_items.id = new.inventory_item_id;
	ELSE 
		UPDATE inventory_items set inventory_items.item_instock = @instock where inventory_items.id = new.inventory_item_id;
    END IF;
END
$$
DELIMITER ;

